author = Author.find_or_create_by(name: 'Materialism') do |a|
  a.biography = 'Materialism is a philosophical theory that asserts that everything that exists is either made of matter or is dependent on matter for its existence, often addressing the mind-body problem in the context of consciousness.'
end

author = Author.find_or_create_by(name: 'Paul Churchland') do |a|
  a.biography = 'Paul Churchland is a prominent philosopher known for his work in the philosophy of mind and neuroscience. He is a leading proponent of eliminative materialism, arguing that common-sense psychological concepts are fundamentally flawed and will be replaced by a neuroscience-based understanding of the mind.'
end

author = Author.find_or_create_by(name: 'Ned Block') do |a|
  a.biography = 'Ned Block is a prominent philosopher of mind known for his work on consciousness and functionalism. He has contributed significantly to the understanding of mental states and their relationship to physical processes, arguing that mental states are defined by their causal relations and functional roles.'
end

author = Author.find_or_create_by(name: 'David Chalmers') do |a|
  a.biography = 'David Chalmers is a philosopher and cognitive scientist known for his work on the philosophy of mind and consciousness. He is particularly recognized for his formulation of the \'hard problem of consciousness\' and his contributions to the debate on emergence in relation to consciousness.'
end

author = Author.find_or_create_by(name: 'J.J.C. Smart') do |a|
  a.biography = 'J.J.C. Smart was an Australian philosopher known for his work in the philosophy of mind, particularly for advocating the mind-brain identity theory, which argues that mental states are identical to brain states.'
end

author = Author.find_or_create_by(name: 'John Searle') do |a|
  a.biography = 'John Searle is an American philosopher known for his work in the philosophy of language, philosophy of mind, and social philosophy. He is particularly recognized for his theory of Biological Naturalism, which addresses the mind-body problem by emphasizing the biological basis of consciousness.'
end

author = Author.find_or_create_by(name: 'Owen Flanagan') do |a|
  a.biography = 'Owen Flanagan is an American philosopher known for his work in philosophy of mind, consciousness, and neurophilosophy. He advocates for a constructive naturalism approach, which seeks to understand consciousness through both subjective experiences and their neural underpinnings, emphasizing the integration of scientific insights with philosophical inquiry.'
end

author = Author.find_or_create_by(name: 'David Papineau') do |a|
  a.biography = 'David Papineau is a philosopher known for his work in the philosophy of mind and science, particularly his advocacy for neurobiological physicalism. He argues that consciousness is fundamentally identical to brain states and critiques dualist perspectives on the mind-body relationship.'
end

author = Author.find_or_create_by(name: 'Rebecca Newberger Goldstein') do |a|
  a.biography = 'Rebecca Newberger Goldstein is an American philosopher and novelist known for her work on the mind-body problem and her exploration of consciousness, identity, and the nature of the self. She has written extensively on the intersection of philosophy and literature, and her novels often delve into complex philosophical themes.'
end

author = Author.find_or_create_by(name: 'Valerie Gray Hardcastle') do |a|
  a.biography = 'Valerie Gray Hardcastle is a philosopher known for her work in the philosophy of mind, particularly her arguments for materialism and her critiques of consciousness skeptics. She emphasizes the importance of empirical investigation in understanding consciousness and has published extensively on the relationship between consciousness and neural correlates.'
end

author = Author.find_or_create_by(name: 'Daniel Stoljar') do |a|
  a.biography = 'Daniel Stoljar is a philosopher known for his work on physicalism and the philosophy of mind. He has critically examined the relationship between consciousness and physicalism, proposing the epistemic view which suggests that our ignorance of certain physical facts is central to understanding the compatibility of physicalism with consciousness.'
end

author = Author.find_or_create_by(name: 'No specific author identified') do |a|
  a.biography = 'This section discusses neurobiological theories of consciousness without attributing the ideas to a specific theorist.'
end

author = Author.find_or_create_by(name: 'Gerald Edelman') do |a|
  a.biography = 'Gerald Edelman was a Nobel laureate biologist known for his work in neuroscience and immunology. He developed the theory of Neural Darwinism, which posits that consciousness arises from the selection of neural circuits based on their functional efficacy, emphasizing the role of both developmental and experiential selection in brain function.'
end

author = Author.find_or_create_by(name: 'Christof Koch') do |a|
  a.biography = 'Christof Koch is a prominent neuroscientist known for his work on the neural correlates of consciousness. He has collaborated with Francis Crick and has contributed significantly to the scientific understanding of consciousness through various research initiatives and theoretical frameworks.'
end

author = Author.find_or_create_by(name: 'Bernard Baars') do |a|
  a.biography = 'Bernard Baars is a cognitive scientist known for his Global Workspace Theory, which posits that consciousness arises from the brain-wide availability of information, likening it to a \'theater of consciousness\' where perceptions compete for attention.'
end

author = Author.find_or_create_by(name: 'Daniel Dennett') do |a|
  a.biography = 'Daniel Dennett is an American philosopher, cognitive scientist, and author known for his work on the philosophy of mind, consciousness, and evolutionary biology. He is a prominent advocate of the multiple drafts model of consciousness, which challenges traditional notions of a central self and emphasizes the role of evolutionary processes in shaping the mind.'
end

author = Author.find_or_create_by(name: 'Marvin Minsky') do |a|
  a.biography = 'Marvin Minsky was a pioneering cognitive scientist and co-founder of the Massachusetts Institute of Technology\'s AI laboratory. He is best known for his work on artificial intelligence and his influential book \'The Society of Mind,\' which presents a theory of human cognition as a collection of semi-independent agents.'
end

author = Author.find_or_create_by(name: 'Michael Graziano') do |a|
  a.biography = 'Michael Graziano is a neuroscientist and professor known for his work on attention schema theory, which explores the relationship between consciousness and the brain\'s representation of attention.'
end

author = Author.find_or_create_by(name: 'Jesse Prinz') do |a|
  a.biography = 'Jesse Prinz is a philosopher known for his work on consciousness and perception, particularly his Attended Intermediate Representation Theory, which argues that consciousness arises from the integration of perceptual information through attention.'
end

author = Author.find_or_create_by(name: 'Robert Sapolsky') do |a|
  a.biography = 'Robert Sapolsky is a neuroendocrinologist and biological anthropologist known for his research on stress and behavior, as well as his views on determinism and free will. He is a professor at Stanford University and has authored several books, including \'Behave\' and \'A Primate\'s Memoir\'.'
end

author = Author.find_or_create_by(name: 'Kevin Mitchell') do |a|
  a.biography = 'Kevin Mitchell is a neuroscientist known for his work on the relationship between free will and consciousness, arguing that agency is not an illusion and that our conscious experiences emerge from the physical workings of the brain.'
end

author = Author.find_or_create_by(name: 'Joscha Bach') do |a|
  a.biography = 'Joscha Bach is a cognitive scientist known for his work on artificial intelligence and consciousness. He is recognized for developing the Cortical Conductor Theory, which provides a functional explanation for phenomenal consciousness, emphasizing the role of cortical structures and their regulation through reward-driven learning.'
end

author = Author.find_or_create_by(name: 'Jaan Aru') do |a|
  a.biography = 'Jaan Aru is a neuroscientist known for his work on consciousness and the Dendritic Integration Theory, which explores the cellular mechanisms underlying conscious experience and the integration of information in the brain.'
end

author = Author.find_or_create_by(name: 'Georg Northoff') do |a|
  a.biography = 'Georg Northoff is a psychiatrist and neuroscientist known for his work on the temporo-spatial theory of consciousness, which emphasizes the role of brain activity and spatiotemporal mechanisms in understanding sentience and consciousness.'
end

author = Author.find_or_create_by(name: 'Mario Bunge') do |a|
  a.biography = 'Mario Bunge was an Argentine philosopher and physicist known for his work in the philosophy of science, particularly in the areas of emergent materialism and the mind-body problem. He advocated for a psychobiological approach to understanding behavior and mental states, emphasizing the importance of a systematic model that integrates neuroscience and social science.'
end

author = Author.find_or_create_by(name: 'William Hirstein') do |a|
  a.biography = 'William Hirstein is a philosopher and cognitive scientist known for his work on consciousness and the mind-body problem, particularly through his thought experiment of \'mindmelding,\' which explores the implications of inter-brain connections for understanding consciousness.'
end

author = Author.find_or_create_by(name: 'John McFadden') do |a|
  a.biography = 'John McFadden is a biophysicist known for his work on the Conscious Electromagnetic Information Theory, which posits that consciousness arises from electromagnetic fields generated by neural activity.'
end

author = Author.find_or_create_by(name: 'Mostyn Jones') do |a|
  a.biography = 'Mostyn Jones is a philosopher known for his work on electromagnetic-field theories of mind, exploring the relationship between consciousness and neural activity. He has proposed the theory of neuroelectrical panpsychism, which suggests that everything is at least minimally conscious and that electrical activity in the brain contributes to the formation of a unified mind.'
end

author = Author.find_or_create_by(name: 'Susan Pockett') do |a|
  a.biography = 'Susan Pockett is a psychologist known for her work on the electromagnetic field theory of consciousness, which posits that conscious experiences are linked to specific electromagnetic patterns generated by the brain, challenging traditional views of consciousness as merely a process.'
end

author = Author.find_or_create_by(name: 'Johnjoe McFadden') do |a|
  a.biography = 'Johnjoe McFadden is a molecular geneticist known for his work on consciousness, particularly his Conscious Electromagnetic Information (CEMI) field theory, which posits that consciousness arises from the brain\'s electromagnetic fields rather than its neuronal matter.'
end

author = Author.find_or_create_by(name: 'Christopher Chen') do |a|
  a.biography = 'Christopher Chen is a neuroscientist known for his work on ephaptic coupling and its implications for neural activity and consciousness, particularly exploring how electric fields generated by neurons can influence neighboring neurons.'
end

author = Author.find_or_create_by(name: 'Richard Ambron') do |a|
  a.biography = 'Richard Ambron is a biologist and pain researcher known for his work on the mechanisms of pain and consciousness. He proposes that understanding the specific consciousness of pain can provide insights into the broader mechanisms of consciousness, particularly through the role of electromagnetic waves generated by neuronal activity.'
end

author = Author.find_or_create_by(name: 'Rodolfo Llinas') do |a|
  a.biography = 'Rodolfo Llinas is a prominent neuroscientist known for his research on the brain\'s oscillatory activity and its implications for cognition, particularly through his theory of the \'mindness state.\''
end

author = Author.find_or_create_by(name: 'Ping Zhang') do |a|
  a.biography = 'Ping Zhang is a synaptic neuroscientist known for his research on the mechanisms of neural communication and synchronization in the brain, proposing theories that explore the relationship between brain activity and consciousness.'
end

author = Author.find_or_create_by(name: 'Nick Bostrom') do |a|
  a.biography = 'Nick Bostrom is a philosopher and futurist known for his work on the implications of future technologies, particularly artificial intelligence and the concept of simulation theory, which posits that our reality could be a computer simulation.'
end

author = Author.find_or_create_by(name: 'Stephen Grossberg') do |a|
  a.biography = 'Stephen Grossberg is a computational neuroscientist known for his work on Adaptive Resonance Theory (ART), which explains how the brain learns to consciously attend, categorize, and predict in a changing environment. His research integrates concepts from cognitive science and neuroscience to explore the mechanisms of consciousness and learning.'
end

author = Author.find_or_create_by(name: 'Steven Rose') do |a|
  a.biography = 'Steven Rose is a prominent neuroscientist and author known for his work on the relationship between brain function and consciousness, as well as his critiques of reductionist approaches in neuroscience.'
end

author = Author.find_or_create_by(name: 'John Beggs') do |a|
  a.biography = 'John Beggs is a biophysicist known for his work on the Critical Brain Hypothesis, which explores how neural networks in the brain operate optimally near a critical point of phase transitions, enhancing information processing and storage.'
end

author = Author.find_or_create_by(name: 'Karl Pribram') do |a|
  a.biography = 'Karl Pribram was a prominent neuroscientist and psychologist known for his Holonomic Brain Theory, which posits that human consciousness arises from quantum effects in the brain, functioning as a holographic storage network. His work has significantly influenced the understanding of memory and consciousness in neuroscience.'
end

author = Author.find_or_create_by(name: 'Bob Doyle') do |a|
  a.biography = 'Bob Doyle is an information philosopher known for his work on the Experience Recorder and Reproducer (ERR), a model that explores the relationship between information, consciousness, and the mind\'s processing of experiences.'
end

author = Author.find_or_create_by(name: 'William Dembski') do |a|
  a.biography = 'William Dembski is a philosopher, theologian, and mathematician known for his work in the field of intelligent design and for developing the concept of \'informational realism,\' which he argues can dissolve the mind-body problem by emphasizing the role of information in defining reality.'
end

author = Author.find_or_create_by(name: 'Roger Penrose') do |a|
  a.biography = 'Roger Penrose is a renowned mathematical physicist and cosmologist known for his work in mathematical physics, particularly in the areas of general relativity and cosmology. He is also recognized for his theories on consciousness, including the idea that consciousness is linked to quantum mechanics and the Platonic realm of mathematical forms.'
end

author = Author.find_or_create_by(name: 'Karl Friston') do |a|
  a.biography = 'Karl Friston is a British neuroscientist known for his work on the free-energy principle and predictive coding, which have significant implications for understanding consciousness and brain function.'
end

author = Author.find_or_create_by(name: 'Andy Clark') do |a|
  a.biography = 'Andy Clark is a cognitive philosopher known for his work on the philosophy of mind and cognitive science, particularly in relation to predictive processing and the extended mind theory.'
end

author = Author.find_or_create_by(name: 'Anil Seth') do |a|
  a.biography = 'Anil Seth is a neuroscientist known for his work on consciousness and perception, particularly his \'beast machine\' theory, which explores how conscious experiences arise from brain-based perceptual predictions.'
end

author = Author.find_or_create_by(name: 'Antonio Damasio') do |a|
  a.biography = 'Antonio Damasio is a prominent neuroscientist and author known for his work on the relationship between emotions, feelings, and consciousness. He has significantly contributed to the understanding of how homeostatic feelings inform decision-making and the regulation of life processes.'
end

author = Author.find_or_create_by(name: 'Mark Solms') do |a|
  a.biography = 'Mark Solms is a neuroscientist and psychoanalyst known for his work on the intersection of neuroscience and psychoanalysis, particularly in relation to consciousness. He applies the free energy principle to understand consciousness, emphasizing the role of affect and the physiological mechanisms underlying it.'
end

author = Author.find_or_create_by(name: 'Robin Carhart-Harris') do |a|
  a.biography = 'Robin Carhart-Harris is a psychopharmacologist known for his research on the effects of psychedelics on the brain and consciousness. He is the proponent of the Entropic Brain Hypothesis, which explores the relationship between brain entropy and conscious states.'
end

author = Author.find_or_create_by(name: 'György Buzsáki') do |a|
  a.biography = 'György Buzsáki is a prominent neuroscientist known for his research on brain oscillations and their role in cognition. He has proposed that the brain functions as a self-organized system that generates actions and examines their consequences, emphasizing the importance of spontaneous neural activity and brain rhythms in cognitive processes.'
end

author = Author.find_or_create_by(name: 'Terrence Deacon') do |a|
  a.biography = 'Terrence Deacon is a neuroanthropologist known for his work in human evolutionary biology and neuroscience. He explores the origins of life and consciousness, emphasizing the role of self-creating and self-sustaining processes in the emergence of consciousness.'
end

author = Author.find_or_create_by(name: 'Antonio Pereira, Jr.') do |a|
  a.biography = 'Antonio Pereira, Jr. is a neuroscientist known for his work on the relationship between sentience and cognitive consciousness. He proposes that cognitive consciousness relies on sentience, emphasizing the physiological aspects of sentience in medical diagnostics and therapy.'
end

author = Author.find_or_create_by(name: 'Warren Mansell') do |a|
  a.biography = 'Warren Mansell is a clinical psychologist known for his work on Perceptual Control Theory (PCT), which explores the relationship between consciousness and the adaptive modification of control systems in response to physiological variables.'
end

author = Author.find_or_create_by(name: 'David Rudrauf') do |a|
  a.biography = 'David Rudrauf is a neuroscientist and researcher known for his work on consciousness, particularly the Projective Consciousness Model, which explores the relationship between phenomenology and cognitive function.'
end

author = Author.find_or_create_by(name: 'Robert Pepperell') do |a|
  a.biography = 'Robert Pepperell is an artist and perceptual scientist known for his work on the relationship between consciousness and energetic activity in the brain. He argues that consciousness is a product of the organization of energetic processes, challenging traditional information-centric views in neuroscience.'
end

author = Author.find_or_create_by(name: 'Francisco Varela') do |a|
  a.biography = 'Francisco Varela was a Chilean biologist, philosopher, and cognitive scientist known for his work in the fields of cognitive science and neurophenomenology, emphasizing the role of the body in consciousness.'
end

author = Author.find_or_create_by(name: 'George Lakoff') do |a|
  a.biography = 'George Lakoff is a cognitive linguist and philosopher known for his work on the relationship between language and thought, particularly in the context of embodied cognition.'
end

author = Author.find_or_create_by(name: 'Evan Thompson') do |a|
  a.biography = 'Evan Thompson is a philosopher and cognitive scientist known for his work on the relationship between life, mind, and consciousness. He is a prominent figure in the field of enactivism, which emphasizes the dynamic interactions between organisms and their environments in understanding cognition and consciousness.'
end

author = Author.find_or_create_by(name: 'Adam Frank') do |a|
  a.biography = 'Adam Frank is an astrophysicist and professor known for his work on the intersection of science and consciousness, advocating for the primacy of consciousness in understanding the universe.'
end

author = Author.find_or_create_by(name: 'Michel Bitbol') do |a|
  a.biography = 'Michel Bitbol is a French philosopher of science and phenomenologist known for his work on neurophenomenology, which explores the relationship between consciousness and the body. He advocates for a radical approach that emphasizes subjective experience and self-transformation in addressing the \'hard problem\' of consciousness.'
end

author = Author.find_or_create_by(name: 'James J. Gibson') do |a|
  a.biography = 'James J. Gibson was an American psychologist known for his work in the field of perception and for developing the theory of Ecological Psychology, which emphasizes the direct interaction between organisms and their environments.'
end

author = Author.find_or_create_by(name: 'Alva Noë') do |a|
  a.biography = 'Alva Noë is a philosopher known for his work in the philosophy of mind and cognitive science, particularly for his theories on consciousness and embodied cognition. He argues that consciousness arises from our interactions with the environment rather than being solely a product of brain activity.'
end

author = Author.find_or_create_by(name: 'Kristjan Loorits') do |a|
  a.biography = 'Kristjan Loorits is a philosopher known for his work on Structural Realism, which explores the nature of consciousness and qualia as structural phenomena in the brain. His theories aim to address the hard problem of consciousness and the issue of privacy in conscious experiences, proposing that qualia are compositional and can be analyzed in structural terms.'
end

author = Author.find_or_create_by(name: 'Nir Lahav') do |a|
  a.biography = 'Nir Lahav is a physicist known for his work on the relationship between consciousness and physical measurements, proposing that consciousness is a physical phenomenon influenced by cognitive frames of reference.'
end

author = Author.find_or_create_by(name: 'Nao Tsuchiya') do |a|
  a.biography = 'Nao Tsuchiya is a neuroscientist known for his relational approach to consciousness, which utilizes category theory to explore the interrelationships of conscious experiences and aims to clarify complex theoretical concepts in the field.'
end

author = Author.find_or_create_by(name: 'William Jaworski') do |a|
  a.biography = 'William Jaworski is a philosopher known for his work on hylomorphism and the philosophy of mind, particularly in relation to consciousness and the mind-body problem. His research explores how structural properties can explain mental phenomena.'
end

author = Author.find_or_create_by(name: 'David Ray Griffin') do |a|
  a.biography = 'David Ray Griffin is a philosopher and theologian known for his work in process philosophy and panexperientialism, particularly in relation to consciousness and the mind-body problem.'
end

author = Author.find_or_create_by(name: 'Michael Tye') do |a|
  a.biography = 'Michael Tye is a prominent philosopher known for his work in the philosophy of mind, particularly in representationalism and the nature of consciousness. He has contributed significantly to discussions on the relationship between mental representation and phenomenal experience.'
end

author = Author.find_or_create_by(name: 'Peter Carruthers') do |a|
  a.biography = 'Peter Carruthers is a philosopher known for his work in the philosophy of mind, particularly in theories of consciousness and representationalism. He has contributed significantly to the debate on first-order representationalism and has critiqued higher-order theories of consciousness.'
end

author = Author.find_or_create_by(name: 'Victor Lamme') do |a|
  a.biography = 'Victor Lamme is a Dutch neuroscientist known for his work on consciousness and visual perception. He is the proponent of Recurrent Processing Theory, which posits that recurrent processing in the brain\'s sensory systems is essential for consciousness.'
end

author = Author.find_or_create_by(name: 'Alexander Durig') do |a|
  a.biography = 'Alexander Durig is a social psychologist known for his work on consciousness and the interaction between the brain\'s hemispheres, proposing that their interactive reflexivity forms the foundation of consciousness.'
end

author = Author.find_or_create_by(name: 'Hakwan Lau') do |a|
  a.biography = 'Hakwan Lau is a cognitive neuroscientist known for his work on consciousness and perception, particularly for developing the Perceptual Reality Monitoring Theory, which explores the relationship between higher-order representations and conscious experience.'
end

author = Author.find_or_create_by(name: 'Joseph LeDoux') do |a|
  a.biography = 'Joseph LeDoux is a prominent neuroscientist known for his research on survival circuits, including their impacts on emotions such as fear and anxiety. He is a leading figure in the study of the neural mechanisms underlying emotional consciousness and has developed the Higher-Order Theory of Emotional Consciousness, which emphasizes the role of higher-order representations in the experience of emotions.'
end

author = Author.find_or_create_by(name: 'Nicholas Humphrey') do |a|
  a.biography = 'Nicholas Humphrey is a British neuropsychologist and author known for his work on consciousness and the evolution of the mind. He proposes a materialistic theory of phenomenal consciousness, emphasizing the role of mental representations and attractor states in the brain, and argues that consciousness is a relatively late evolutionary development.'
end

author = Author.find_or_create_by(name: 'Thomas Metzinger') do |a|
  a.biography = 'Thomas Metzinger is a German philosopher and cognitive scientist known for his work on consciousness and the philosophy of mind. He is particularly recognized for his no-self model, which argues that the self is an illusion and that what we perceive as selfhood is a dynamic process of phenomenal experience.'
end

author = Author.find_or_create_by(name: 'Frank Jackson') do |a|
  a.biography = 'Frank Jackson is an Australian philosopher known for his work in the philosophy of mind, particularly for his knowledge argument against physicalism and his development of the theory of Diaphanous Representationalism, which posits that perceptual experiences are fundamentally tied to the properties of the objects being perceived.'
end

author = Author.find_or_create_by(name: 'William Lycan') do |a|
  a.biography = 'William Lycan is a prominent philosopher known for his work in the philosophy of mind, particularly for developing the theory of homuncular functionalism. He defends a materialist view of consciousness, emphasizing the representational nature of mental states and the importance of functional organization in understanding the mind.'
end

author = Author.find_or_create_by(name: 'William G. Lycan') do |a|
  a.biography = 'William G. Lycan is an American philosopher known for his work in the philosophy of mind, particularly in consciousness and materialism. He has contributed significantly to discussions on transparency theory and the nature of perceptual experience.'
end

author = Author.find_or_create_by(name: 'Paul Thagard') do |a|
  a.biography = 'Paul Thagard is a philosopher and cognitive scientist known for his work on the nature of consciousness and the mechanisms underlying it. He has developed a theory that attributes conscious experiences to the interactions of four brain mechanisms: neural representation, binding, coherence, and competition, and emphasizes an empirically based approach to understanding consciousness.'
end

author = Author.find_or_create_by(name: 'Thomas Clark') do |a|
  a.biography = 'Thomas Clark is a philosopher known for his work on consciousness and cognitive systems, particularly his Content Hypothesis, which explores the nature of phenomenal consciousness and its representational content.'
end

author = Author.find_or_create_by(name: 'Noam Chomsky') do |a|
  a.biography = 'Noam Chomsky is a linguist, philosopher, cognitive scientist, historian, and social critic, widely known for his theory of generative grammar and his contributions to the study of language and its relation to the mind.'
end

author = Author.find_or_create_by(name: 'Barry Smith') do |a|
  a.biography = 'Barry Smith is a philosopher known for his work in the philosophy of language and the philosophy of mind. He explores the relationship between language and consciousness, emphasizing how language shapes our understanding and categorization of experiences.'
end

author = Author.find_or_create_by(name: 'Julian Jaynes') do |a|
  a.biography = 'Julian Jaynes was an American psychologist and author best known for his controversial theory of the bicameral mind, which suggests that consciousness is a learned behavior that emerged in humans relatively recently in history. His influential work, \'The Origin of Consciousness in the Breakdown of the Bicameral Mind,\' published in 1976, argues that early humans experienced auditory hallucinations and made decisions based on these external voices, which he equated to gods.'
end

author = Author.find_or_create_by(name: 'John Parrington') do |a|
  a.biography = 'John Parrington is a biologist and author known for his work on the evolution of consciousness, particularly focusing on the role of language and tool use in shaping human self-awareness and cognitive abilities.'
end

author = Author.find_or_create_by(name: 'Theodosius Dobzhansky') do |a|
  a.biography = 'Theodosius Dobzhansky was a prominent geneticist and evolutionary biologist, known for his work in the field of population genetics and for his famous adage, \'Nothing in biology makes sense except in the light of evolution.\' His research significantly contributed to the modern synthesis of evolutionary theory.'
end

author = Author.find_or_create_by(name: 'Simona Ginsburg') do |a|
  a.biography = 'Simona Ginsburg is a neurobiologist known for her work on the evolution of consciousness and learning, particularly in collaboration with Eva Jablonka.'
end

author = Author.find_or_create_by(name: 'Stanislas Dehaene') do |a|
  a.biography = 'Stanislas Dehaene is a French neuroscientist known for his work on the cognitive neuroscience of consciousness, numerical cognition, and the brain mechanisms underlying reading and arithmetic.'
end

author = Author.find_or_create_by(name: 'Kristin Andrews') do |a|
  a.biography = 'Kristin Andrews is a philosopher and expert on animal minds, known for her work on consciousness studies and the philosophy of animal cognition. She advocates for a broader understanding of consciousness that includes simpler organisms, challenging the conventional view that complex brains are necessary for conscious experience.'
end

author = Author.find_or_create_by(name: 'Arthur Reber') do |a|
  a.biography = 'Arthur Reber is a cognitive psychologist known for his work on the Cellular Basis of Consciousness (CBC), which argues that consciousness is an inherent feature of all living organisms, including the most primitive forms of life. He challenges traditional views of mind and consciousness as unique to complex brains, emphasizing the evolutionary and biological foundations of sentience.'
end

author = Author.find_or_create_by(name: 'Todd Feinberg') do |a|
  a.biography = 'Todd Feinberg is a neurologist and psychiatrist known for his work on consciousness and the evolution of the mind, particularly in collaboration with Jon Mallatt, exploring the origins of consciousness in vertebrates and invertebrates.'
end

author = Author.find_or_create_by(name: 'Michael Levin') do |a|
  a.biography = 'Michael Levin is a developmental and synthetic biologist known for his work on the Technological Approach to Mind Everywhere (TAME), which explores cognition in unconventional substrates and challenges traditional concepts in the philosophy of mind.'
end

author = Author.find_or_create_by(name: 'William James') do |a|
  a.biography = 'William James was an American philosopher and psychologist, widely regarded as one of the most influential figures in the development of psychology and philosophy in the late 19th and early 20th centuries. He is best known for his work on the philosophy of pragmatism and his theories on consciousness, particularly his view that consciousness serves to select adaptive responses to environmental challenges.'
end

author = Author.find_or_create_by(name: 'George Ellis') do |a|
  a.biography = 'George Ellis is a mathematical physicist known for his work in cosmology and the philosophy of science. He has made significant contributions to the understanding of strong emergence and top-down causation, particularly in relation to consciousness and the nature of existence.'
end

author = Author.find_or_create_by(name: 'Nancey Murphy') do |a|
  a.biography = 'Nancey Murphy is a Christian philosopher known for her work in the philosophy of mind and theology, particularly her advocacy for Non-Reductive Physicalism, which seeks to reconcile physicalist views with Christian anthropology. She has contributed significantly to discussions on the implications of cognitive science for understanding human nature.'
end

author = Author.find_or_create_by(name: 'Yujin Nagasawa') do |a|
